node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage();
  await page.goto('http://127.0.0.1:8765');
  await page.locator('[data-action="start-jumble"]').first().click();
  for (let q = 0; q < 3; q++) {
    const data = await page.evaluate(() => ({ answer: game.items[game.index].verb[game.items[game.index].key], scrambled: [...game.scrambled] }));
    const indexes = [];
    for (const letter of data.answer) indexes.push(data.scrambled.findIndex((candidate, i) => candidate === letter && !indexes.includes(i)));
    for (const idx of indexes) await page.locator(`[data-action="add-letter"][data-index="${idx}"]`).click();
    await page.locator('[data-action="jumble-check"]').click();
    const feedback = await page.locator('.feedback').innerText();
    if (!feedback.includes('Beautifully grown')) throw new Error(`Q${q + 1} incorrect: ${feedback}; expected ${data.answer}`);
    if (q < 2) await page.locator('[data-action="game-next"]').click();
  }
  await page.locator('[data-action="game-next"]').click();
  const completion = await page.locator('.completion').innerText();
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('verbana-save')));
  console.log(JSON.stringify({ completion: completion.includes('A PERFECT LITTLE ROUND'), coins: saved.coins, perfect: saved.perfect, rounds: saved.rounds }, null, 2));
  if (!completion.includes('A PERFECT LITTLE ROUND') || saved.coins !== 45 || saved.perfect !== 1 || saved.rounds !== 1) throw new Error('Perfect round reward/save verification failed');
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
